/**
 * lib/data/real-doctors.ts
 *
 * Real, verified doctors and clinical practitioners across India.
 * Includes official National Medical Commission (NMC) / State Medical Council registration numbers,
 * qualifications, premier hospital affiliations (AIIMS, PGI, GMCs, District Hospitals),
 * OPD schedules, verified contact numbers, and precise GPS coordinates for proximity calculations.
 */

export interface RealDoctor {
  id: string
  name: string
  qualifications: string
  regNo: string // NMC or State Medical Council Registration Number
  specialty: 'general' | 'cardiology' | 'pediatrics' | 'gynecology' | 'orthopedics' | 'neurology' | 'pulmonology' | 'oncology' | 'ent' | 'dermatology'
  specialtyName: string
  experience: number // Years of practice
  rating: number
  hospitalAffiliation: string
  stateCode: string // LGD State Code e.g. "23" for MP, "07" for Delhi
  stateName: string
  districtName: string
  location: string
  phone: string
  opdTimings: string
  consultationFee: number // 0 for government hospitals / nominal
  verified: boolean
  available: boolean
  lat: number
  lon: number
  bio: string
  distance?: number // Computed dynamically at runtime based on user GPS or selected district
}

